package com.rikkeibank.transaction.service;
import com.fasterxml.jackson.databind.ObjectMapper; import com.rikkeibank.transaction.dto.*; import com.rikkeibank.transaction.event.TransferEvent; import com.rikkeibank.transaction.model.*; import com.rikkeibank.transaction.repository.BankTransactionRepository; import java.time.*; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service public class TransactionService{private final BankTransactionRepository repo;private final TransactionEntryRepository entryRepo;private final AccountClientFacade accounts;private final KafkaTemplate<String,String> kafka;private final ObjectMapper mapper;private final String completedTopic;private final String failedTopic;public TransactionService(BankTransactionRepository r,TransactionEntryRepository er,AccountClientFacade a,KafkaTemplate<String,String> k,ObjectMapper m,@Value("${app.kafka.transfer-completed-topic:transfer.completed}")String ct,@Value("${app.kafka.transfer-failed-topic:transfer.failed}")String ft){repo=r;entryRepo=er;accounts=a;kafka=k;mapper=m;completedTopic=ct;failedTopic=ft;}
 public BankTransaction transfer(TransferRequest req,String username){if(req.sourceAccountId().equals(req.targetAccountId()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Tài khoản nguồn và đích phải khác nhau");String op=UUID.randomUUID().toString();BankTransaction tx=new BankTransaction();tx.setOperationId(op);tx.setSourceAccountId(req.sourceAccountId());tx.setTargetAccountId(req.targetAccountId());tx.setAmount(req.amount());tx.setInitiatorUsername(username);tx.setStatus(TransactionStatus.PENDING);tx=repo.save(tx);boolean debit=false,credit=false;try{accounts.debit(new AccountOperationRequest(req.sourceAccountId(),username,req.amount(),op));debit=true;accounts.credit(new AccountOperationRequest(req.targetAccountId(),null,req.amount(),op));credit=true;tx.setStatus(TransactionStatus.COMPLETED);tx.setCompletedAt(LocalDateTime.now());tx=repo.save(tx);saveEntry(tx.getId(),req.sourceAccountId(),"DEBIT",req.amount());saveEntry(tx.getId(),req.targetAccountId(),"CREDIT",req.amount());publish(completedTopic,new TransferEvent("TRANSFER_COMPLETED",tx.getId(),op,req.sourceAccountId(),req.targetAccountId(),req.amount(),username,"Transfer completed",Instant.now()));return tx;}catch(Exception ex){try{if(credit)accounts.compensateCredit(new AccountOperationRequest(req.targetAccountId(),null,req.amount(),op));if(debit)accounts.compensateDebit(new AccountOperationRequest(req.sourceAccountId(),username,req.amount(),op));}catch(Exception ignored){}tx.setStatus(TransactionStatus.FAILED);tx.setFailureReason(ex.getMessage());tx=repo.save(tx);publish(failedTopic,new TransferEvent("TRANSFER_FAILED",tx.getId(),op,req.sourceAccountId(),req.targetAccountId(),req.amount(),username,ex.getMessage(),Instant.now()));throw ex;}}
 private void saveEntry(Long txId,Long accountId,String type,java.math.BigDecimal amount){TransactionEntry e=new TransactionEntry();e.setTransactionId(txId);e.setAccountId(accountId);e.setEntryType(type);e.setAmount(amount);entryRepo.save(e);}
 public List<TransactionEntry> entries(Long transactionId){find(transactionId);return entryRepo.findAllByTransactionIdOrderById(transactionId);}
 public List<BankTransaction> history(String username){return repo.findAllByInitiatorUsernameOrderByCreatedAtDesc(username);}public List<BankTransaction> todayForTeller(String teller){LocalDate d=LocalDate.now();return repo.findAllByAssignedTellerUsernameAndCreatedAtBetweenOrderByCreatedAtDesc(teller,d.atStartOfDay(),d.plusDays(1).atStartOfDay());}@Transactional public BankTransaction assign(Long id,String teller){BankTransaction tx=find(id);tx.setAssignedTellerUsername(teller);return repo.save(tx);}@Transactional public BankTransaction review(Long id,String teller){BankTransaction tx=find(id);if(!Objects.equals(teller,tx.getAssignedTellerUsername()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Không được xử lý giao dịch của giao dịch viên khác");tx.setReviewed(true);return repo.save(tx);}public BankTransaction find(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy giao dịch"));}
 private void publish(String topic,TransferEvent event){try{kafka.send(topic,event.operationId(),mapper.writeValueAsString(event));}catch(Exception ignored){}}
}
